299	/// except that the bundle-root index MAY carry a block declaring only
300	/// `okf_version` (§11). Any other leading `---` block is a warning.
301	pub fn okf_index_reports(raw: &str) -> Vec<LintReport> {
302	    let mut reports = Vec::new();
303	    let trimmed = raw.trim_start();
304	    if let Some(rest) = trimmed.strip_prefix("---") {
305	        if let Some(end) = rest.find("\n---") {
306	            let fm = &rest[..end];
307	            let only_okf_version = fm
308	                .lines()
309	                .filter(|l| !l.trim().is_empty())
310	                .all(|l| l.trim_start().starts_with("okf_version"));
